<script setup lang="ts">
import { computed, reactive, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Refresh, ShoppingCart } from '@element-plus/icons-vue';
import { api } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { useSessionStore } from '../stores/session';
import { formatFen, shanghaiTime } from '../domain/m1';
import { parseM2Filters, m2Query, intentStates, purchaseStates, stateNames } from '../domain/m2';
import ErrorPanel from '../components/ErrorPanel.vue';
import PagePagination from '../components/PagePagination.vue';
import StatusBadge from '../components/StatusBadge.vue';
const route=useRoute();const router=useRouter();const session=useSessionStore();
const intents=computed(()=>route.query.view==='intents');const filters=computed(()=>{const value=parseM2Filters(route.query);if(!intents.value&&!purchaseStates.includes(value.state as never))delete value.state;return value;});
const purchases=useRemote(()=>api.listPurchases(filters.value));const intentList=useRemote(()=>api.listIntents(filters.value));const stores=useRemote(()=>api.listStores(100,0));
const current=computed(()=>intents.value?intentList:purchases);const states=computed(()=>intents.value?intentStates:purchaseStates);const form=reactive({storeId:'',state:''});
watch(()=>route.fullPath,()=>{form.storeId=filters.value.storeId??'';form.state=filters.value.state??'';void current.value.load();},{immediate:true});void stores.load();
function apply(){void router.push({path:'/purchases',query:{...m2Query({...filters.value,...form,offset:0},['storeId','state']),...(intents.value?{view:'intents'}:{})}});}
function view(value:boolean){void router.push({path:'/purchases',query:{...m2Query({...filters.value,state:undefined,offset:0},['storeId','state']),...(value?{view:'intents'}:{})}});}
function paginate(offset:number,limit:number){void router.push({path:'/purchases',query:{...m2Query({...filters.value,offset,limit},['storeId','state']),...(intents.value?{view:'intents'}:{})}});}
</script>
<template>
  <div>
    <div class="page-heading"><div><p class="eyebrow">业务管理 / 采购管理</p><h1>采购管理</h1><p class="muted">Mock 采购意图与采购单分别记录 · 创建成功仅为待付款 · 时间：Asia/Shanghai</p></div><el-button :icon="Refresh" :loading="current.loading.value" @click="current.load">刷新状态</el-button></div><div class="catalog-tabs"><button type="button" :class="{active:!intents}" @click="view(false)">采购订单</button><button type="button" :class="{active:intents}" @click="view(true)">采购意图 / 异步进度</button></div><p class="scope-hint">结果未知时后台只查 Mock 权威状态，请勿重新下单；付款状态在支付中心独立核验，真实平台待授权。</p>
    <section class="panel filter-panel"><form data-testid="purchase-filters" class="filter-form" @submit.prevent="apply"><label>店铺<select v-model="form.storeId" name="storeId"><option value="">全部可见店铺</option><option v-for="store in stores.data.value?.items" :key="store.id" :value="store.id">{{ store.displayName }}</option></select></label><label>采购状态<select v-model="form.state" name="state"><option value="">全部状态</option><option v-for="state in states" :key="state" :value="state">{{ stateNames[state] }}</option></select></label><div class="filter-actions"><el-button native-type="submit" type="primary">查询</el-button><RouterLink v-if="session.can('sourcing.manage')" to="/catalog/sourcing"><el-button>审核货源与规则</el-button></RouterLink></div></form><p v-if="stores.data.value&&stores.data.value.total>100" class="help-text muted">选择器显示前 100 个可见店铺，可使用含 storeId 的采购链接筛选其他店铺。</p><ErrorPanel v-if="stores.error.value" :error="stores.error.value" title="店铺筛选读取失败"><el-button @click="stores.load">重试店铺</el-button></ErrorPanel></section>
    <section class="panel table-panel" :aria-busy="current.loading.value"><div v-if="current.loading.value" class="data-state" role="status"><el-skeleton :rows="4" animated /><p>正在加载 {{ intents?'采购意图':'采购订单' }}…</p></div><ErrorPanel v-else-if="current.error.value" :error="current.error.value" title="采购记录读取失败"><el-button @click="current.load">重试</el-button></ErrorPanel><div v-else-if="current.data.value&&!current.data.value.items.length" data-testid="purchases-empty" class="data-state"><el-icon class="empty-icon"><ShoppingCart /></el-icon><h2>暂无匹配{{ intents?'采购意图':'采购订单' }}</h2><p>{{ intents?'确认 SKU 映射并满足采购规则后，可生成唯一采购意图。':'后台正在创单的记录可在“采购意图 / 异步进度”查看。' }}</p></div><div v-else-if="intents&&intentList.data.value" class="table-scroll"><table class="data-table"><thead><tr><th>意图 / 销售子项</th><th>状态</th><th>预计到手成本</th><th>最近更新（上海）</th><th>操作</th></tr></thead><tbody><tr v-for="intent in intentList.data.value.items" :key="intent.id"><td><RouterLink class="text-link mono" :to="`/purchase-intents/${intent.id}`">{{ intent.id }}</RouterLink><small class="mono">子项 {{ intent.salesOrderItemId }}</small></td><td><StatusBadge kind="procurement" :status="intent.state" /><small v-if="intent.failureCode">{{ intent.failureCode }}</small></td><td class="money-cell">{{ formatFen(intent.estimatedTotalFen) }}<small>CNY · 数量 {{ intent.qty }} · {{ intent.state==='PAID'?'Mock 已付':'见付款记录' }}</small></td><td class="time-cell">{{ shanghaiTime(intent.updatedAt) }}</td><td><RouterLink class="text-link" :to="`/purchase-intents/${intent.id}`">查看进度</RouterLink></td></tr></tbody></table></div><div v-else-if="!intents&&purchases.data.value" class="table-scroll"><table class="data-table"><thead><tr><th>采购单 / 外部 Mock 单号</th><th>状态</th><th>采购金额</th><th>最近更新（上海）</th><th>操作</th></tr></thead><tbody><tr v-for="purchase in purchases.data.value.items" :key="purchase.id"><td><RouterLink class="text-link mono" :to="`/purchases/${purchase.id}`">{{ purchase.id }}</RouterLink><small class="mono">{{ purchase.externalOrderId??'尚未取得权威单号' }}</small></td><td><StatusBadge kind="procurement" :status="purchase.state" /></td><td class="money-cell">{{ formatFen(purchase.totalFen) }}<small>CNY · {{ purchase.state==='PAID'?'Mock 已付':'见独立付款记录' }}</small></td><td class="time-cell">{{ shanghaiTime(purchase.updatedAt) }}</td><td><RouterLink class="text-link" :to="`/purchases/${purchase.id}`">查看详情</RouterLink></td></tr></tbody></table></div><PagePagination v-if="current.data.value" :total="current.data.value.total" :limit="filters.limit" :offset="filters.offset" :loading="current.loading.value" @change="paginate" /></section>
  </div>
</template>
